-- 4. Ingest power outages from power_outages.csv
create table if not exists power_outages_log (
    outage_id varchar(32) primary key,
    facility_code varchar(32) not null,
    start_time timestamptz not null,
    end_time timestamptz not null,
    duration_hours double precision not null,
    backup_power_engaged boolean not null,
    created_at timestamptz not null default now()
);
create index if not exists idx_power_outages_facility on power_outages_log (facility_code);
