-- 5. Ingest blood donation drives from drives.csv
create table if not exists blood_drives_log (
    drive_id varchar(32) primary key,
    drive_date date not null,
    collecting_site_code varchar(32) not null,
    county varchar(120),
    venue_type varchar(80),
    registered_donors integer not null default 0,
    donations_collected integer not null default 0,
    donors_deferred integer not null default 0,
    created_at timestamptz not null default now()
);
create index if not exists idx_blood_drives_site on blood_drives_log (collecting_site_code);
create index if not exists idx_blood_drives_date on blood_drives_log (drive_date);
