-- 6. Ingest historical requests table
create table if not exists historical_requests_log (
    request_id varchar(32) primary key,
    facility_code varchar(32) not null,
    facility_name_raw varchar(255),
    requested_at timestamptz not null,
    clinical_indication varchar(80),
    patient_sex varchar(10),
    patient_age_band varchar(20),
    patient_blood_group varchar(20),
    component_requested varchar(32),
    units_requested integer not null,
    urgency varchar(32),
    units_issued integer not null,
    outcome varchar(32),
    created_at timestamptz not null default now()
);
create index if not exists idx_historical_requests_fac on historical_requests_log (facility_code);
create index if not exists idx_historical_requests_date on historical_requests_log (requested_at);
